// src/App.js
import React, { useState, useEffect } from "react";
import { BrowserRouter as Router, Route, Switch } from "react-router-dom";
import goStemLogo from './components/GoStemLogo.png';
import './styles/App.css';

import LandingPage from "./landing-page";
import NotePage from "./note-page";
import ChatPage from "./chats-page";
import HoursPage from "./hours-page";
import ProfilePage from "./profile-page";
import SchedulePage from "./schedule-page";
import AdminSchedulePage from "./admin/admin-schedule-page";

function App() {
  // Default role is "user". If the logged-in user is staff, we'll set this to "admin"
  const [userRole, setUserRole] = useState('user');

  useEffect(() => {
    // Fetch user info from the backend endpoint
    fetch('http://localhost:8000/api/schedule/get_user_info/', {
      credentials: 'include', // necessary for session authentication
    })
      .then((res) => {
        if (!res.ok) {
          throw new Error(`HTTP error! Status: ${res.status}`);
        }
        return res.json();
      })
      .then((data) => {
        if (data.is_staff) {
          setUserRole('admin');
        }
      })
      .catch((err) => {
        console.error("Error fetching user info:", err);
        // You might want to handle errors or redirect to login here.
      });
  }, []);

  return (
    <Router>
      <Switch>
        <Route exact path="/" component={Home} />
        <Route path="/landing-page" component={LandingPage} />
        <Route path="/note-page" component={NotePage} />
        <Route path="/chats-page" component={ChatPage} />
        <Route path="/hours-page" component={HoursPage} />
        <Route path="/profile-page" component={ProfilePage} />
        {/* Pass the userRole prop to SchedulePage */}
        <Route 
          path="/schedule-page" 
          render={(props) => <SchedulePage {...props} userRole={userRole} />} 
        />
        {/* Optionally, pass userRole to admin-specific routes as needed */}
        <Route 
          path="/admin-schedule-page" 
          render={(props) => <AdminSchedulePage {...props} userRole={userRole} />} 
        />
      </Switch>
    </Router>
  );
}

const Home = () => {
  return (
    <div className="App">
      <header className="Landing-page">
        <img src={goStemLogo} className="App-logo" alt="logo" />
        <a href="/accounts/google/login/?process=login">
          <button className="Login-button">
            Login
          </button>
        </a>
      </header>
    </div>
  );
};

export default App;
